insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000010', 1, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/01.jpg" alt="We don’t have to have everything to give someone something that matters.">', '<p><strong>Opening</strong></p><p>&bull; Tios: we&rsquo;d drop in on family&hellip;unannounced.</p><p>&bull; Lucas and Mary: they just got married.</p><p>&bull; Sometimes the greatest thing a family passes down isn&rsquo;t what they own. It&rsquo;s how they treat people.</p><p>&bull; <strong>We don&rsquo;t have to have everything to give someone something that matters.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 2, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/02.jpg" alt="We didn’t have great teachers — Marriage Enrichment Seminar, His Needs, Her Needs, and books by Dr. James Dobson">', '<p><strong>We didn&rsquo;t have great teachers&hellip;</strong></p><p>&bull; James Dobson</p><p>&bull; Paul Faulkner, Carl Brecheen</p><p>&bull; Hadn&rsquo;t read books like &ldquo;His Needs, Her Needs&rdquo;</p><p><strong>There&rsquo;s hope for every generation:</strong> we don&rsquo;t have to start from scratch. What if we could discover what really matters and pass it on? Build our families on what lasts? Give the next generation a strong foundation?</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 3, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/03.jpg" alt="1 Corinthians 3:10–11">', '<p><strong>1 Corinthians 3:10&ndash;17</strong></p><p>&bull; There&rsquo;s division in the church.</p><p>&bull; Paul: you are &ldquo;infants&rdquo; not ready for solid food.</p><p>&bull; Addresses the controversy over &ldquo;Paul&rdquo; and &ldquo;Apollos.&rdquo;</p><p>&bull; Verses 10&ndash;17 are about building on the right foundation.</p><p>&bull; The principle speaks strongly to the very challenges of a family.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 4, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/04.jpg" alt="1 Corinthians 3:12–13">', '<p>Gold, silver, costly stones, wood, hay or straw &mdash; the Day will bring it to light.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 5, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/05.jpg" alt="1 Corinthians 3:14–15">', '<p>Lives can be built on questionable foundations: a painful foundation; a promising foundation abandoned; two very different beginnings. Both need something to change.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 6, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/06.jpg" alt="Healing doesn’t change what happened yesterday. It changes what we carry into tomorrow.">', '<p><strong>Joyce Meyer</strong></p><p>&bull; Not everyone grows up in a loving, supportive family. Some family experiences can leave wounds.</p><p>&bull; Sometimes the very people who should have protected us are the ones who hurt us the most.</p><p><strong>[Video: Joyce Meyer &mdash; Her Story]</strong></p><p>&bull; What gets passed down doesn&rsquo;t always have to get passed on.</p><p>&bull; We may inherit a painful beginning, but we can build a different future.</p><p>&bull; <strong>Healing doesn&rsquo;t change what happened yesterday. It changes what we carry into tomorrow.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 7, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/07.jpg" alt="The past doesn’t have to be the future.">', '<p>&ldquo;The past doesn&rsquo;t have to be the future.&rdquo;</p><p>Some people spend their adult lives trying to heal from what happened in their childhood.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 8, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/08.jpg" alt="Sometimes we walk away from the very things that gave us a strong foundation.">', '<p><strong>Damon West</strong></p><p>&bull; Not everyone who grows up in a loving, supportive family makes good choices.</p><p>&bull; Sometimes we walk away from the very things that gave us a strong foundation.</p><p>&bull; Damon West had a promising future &mdash; a college quarterback, a successful career, and parents who loved and supported him. But his choices took him down a very different path.</p><p><strong>[Video: Damon West &mdash; The Coffee Bean Story]</strong></p><p>&bull; &ldquo;A good foundation doesn&rsquo;t guarantee good choices, but it gives us something worth returning to.&rdquo;</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 9, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/09.jpg" alt="Sometimes holding on to what is good means returning to what we’ve forgotten.">', '<p>&bull; Sometimes holding on to what is good means letting go of what has hurt us.</p><p>&bull; And sometimes it means returning to what we&rsquo;ve forgotten.</p><p>&bull; Mom: &ldquo;You come back as the man we raised.&rdquo; She was confident about how she raised him.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 10, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/10.jpg" alt="Hope begins when someone reminds us of who we can still become.">', '<p>&bull; Hope begins when someone reminds us of who we can still become.</p><p>&bull; His parents couldn&rsquo;t undo his choices, but they could remind him of his foundation.</p><p>&bull; A good foundation doesn&rsquo;t guarantee good choices. But it gives us something worth returning to.</p><p>Some people spend their adult lives trying to recover what they walked away from.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 11, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/11.jpg" alt="Both discovered that their beginning didn’t have to determine their ending.">', '<p><strong>There is still hope for the family</strong></p><p>&bull; Joyce &mdash; breaking the cycle, building something new.</p><p>&bull; Damon &mdash; rediscovering what was good, returning to his foundation.</p><p>&bull; Joyce Meyer had to overcome much of what she inherited. Damon West had to rediscover much of what he inherited.</p><p>&bull; <strong>Both discovered that their beginning didn&rsquo;t have to determine their ending.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000010', 12, '<img class="slide-image" src="/sermons/hope-for-the-family/slides/12.jpg" alt="We don’t have to hold on to everything from our past to hold on to what is good.">', '<p><strong>Closing</strong></p><p>&bull; 1 Thessalonians 5:21 &mdash; &ldquo;Hold on to what is good!&rdquo;</p><p>&bull; <strong>We don&rsquo;t have to hold on to everything from our past to hold on to what is good.</strong></p><p>&bull; You cannot rewrite the beginning of your family&rsquo;s story.</p><p>&bull; But (with God&rsquo;s help) you can influence what happens in the next chapter.</p><p>&bull; The foundation matters.</p><p>Tomorrow&rsquo;s families are counting on the foundation that we are building today.</p>', null, null)
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
